<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { api, ApiError } from './api'
import './risk.css'
type Row = Record<string,any>
const emit=defineEmits<{expired:[]}>()
const activeTab=ref('people')
const error=ref(''),message=ref(''),busy=ref(false),query=ref(''),people=ref<Row[]>([]),risk=ref<Row|null>(null),pending=ref<Row[]>([]),record=ref<Row|null>(null),candidates=ref<Row[]>([]),recordId=ref(''),rules=ref<Row[]>([])
const decision=ref('INDEPENDENT'),target=ref<number|null>(null),reason=ref(''),tags=ref(''),tagReason=ref('')
const riskType=(value:string)=>value==='HIGH'?'danger':value==='MEDIUM'?'warning':'success'
const level=(value:string)=>({LOW:'低风险',MEDIUM:'中风险',HIGH:'高风险'}[value]||value)
const formatTime=(value:string)=>value?value.replace('T',' '):'—'
const descriptionSummary=(value?:string)=>{const text=value?.replace(/\s+/g,' ').trim()||'暂无描述';return text.length>30?text.slice(0,30)+'…':text}
const historyDecision=(value:string)=>({MERGE:'确认重复并归集',MERGED:'确认重复并归集',INDEPENDENT:'确认独立有效'}[value]||'未知结论')
const state=(value:string)=>({PENDING:'身份待审',CONFIRMED:'身份已确认',SCREENED:'筛查完成',SUSPECTED:'疑似重复待审',INDEPENDENT:'独立有效',MERGED:'已归集'}[value]||value)
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await action()}catch(e){error.value=e instanceof Error?e.message:'操作失败';if(e instanceof ApiError&&e.status===401)emit('expired')}finally{busy.value=false}}
async function refresh(){people.value=await api('/intake/people?q='+encodeURIComponent(query.value));pending.value=await api('/intake/duplicate-reviews')}
async function openRisk(id:number){risk.value=await api('/intake/people/'+id+'/risk')}
async function openRecord(id:number){const nextRecord=await api<Row>('/intake/records/'+id);const nextCandidates=await api<Row[]>('/intake/records/'+id+'/duplicates');record.value=nextRecord;candidates.value=nextCandidates;recordId.value=String(id);decision.value='INDEPENDENT';tags.value=nextRecord.keyword_tags??'';target.value=null;reason.value='';tagReason.value='';activeTab.value='source'}
async function review(){await api(`/intake/records/${record.value!.id}/duplicate-review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({version:record.value!.version,decision:decision.value,targetRecordId:target.value,reason:reason.value})});await openRecord(record.value!.id);await refresh();if(risk.value)await openRisk(risk.value.personId);message.value='重复审核已保存，风险已重算'}
async function saveTags(){await api(`/intake/records/${record.value!.id}/tags`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({version:record.value!.version,tags:tags.value,reason:tagReason.value})});await openRecord(record.value!.id);if(risk.value)await openRisk(risk.value.personId);message.value='标签已保存，关键词及风险已重新计算'}
onMounted(()=>run(async()=>{await refresh();rules.value=await api('/intake/keyword-rules')}))
</script>
<template>
<main class="content risk-workspace"><div class="page-heading"><div><p class="eyebrow">中心研判 / RISK ANALYSIS</p><h1>归集与风险</h1><p class="muted">从来源核查到风险研判，每一项结论都有据可循。</p></div><el-tag effect="plain" type="success">中心研判工作台</el-tag></div>
<div class="risk-guide"><div><b>01</b><span><strong>核对来源</strong><small>保留每条上报与原始依据</small></span></div><div><b>02</b><span><strong>确认归集</strong><small>独立有效事件参与次数累计</small></span></div><div><b>03</b><span><strong>研判风险</strong><small>结合规则命中与人工调整</small></span></div></div>
<el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="message" :title="message" type="success" :closable="false"/>
<p v-if="busy" class="risk-loading" role="status">正在处理，请稍候…</p>
<el-tabs v-model="activeTab" class="risk-tabs" :aria-busy="busy">
<el-tab-pane name="people" label="人员风险档案"><section class="event-card"><div class="card-heading"><div><h2>人员风险档案 <span>{{people.length}}</span></h2><p class="muted">检索人员，查看有效事件与风险形成依据。</p></div></div><form class="filter-bar" @submit.prevent="run(refresh)"><label class="risk-query"><span>查找人员</span><el-input v-model="query" aria-label="筛选风险档案" placeholder="姓名、身份证或手机号" clearable/></label><el-button type="primary" native-type="submit" :loading="busy">查询档案</el-button><el-button :disabled="busy" @click="query='';run(refresh)">重置</el-button></form>
<el-table :data="people" empty-text="暂无符合条件的人员档案"><el-table-column prop="name" label="姓名" min-width="150" show-overflow-tooltip/><el-table-column prop="idCard" label="身份证" min-width="190"/><el-table-column prop="phone" label="手机号" min-width="140"/><el-table-column label="操作" width="140"><template #default="{row}"><el-button link type="primary" :disabled="busy" @click="run(()=>openRisk(row.id))">查看风险依据</el-button></template></el-table-column></el-table>
<section v-if="risk" class="risk-detail"><div class="risk-detail-heading"><div><p class="eyebrow">风险档案 / #{{risk.personId}}</p><h2>人员 #{{risk.personId}} 风险依据</h2></div><el-tag :type="riskType(risk.finalLevel)" effect="light" size="large">{{level(risk.finalLevel)}}</el-tag></div>
<div class="risk-metrics"><div><span>有效事件次数</span><strong>{{risk.effectiveCount}}</strong><small>独立有效事件计数</small></div><div><span>来源上报记录数</span><strong>{{risk.sourceCount}}</strong><small>保留全部关联来源记录</small></div><div><span>关键词命中</span><strong>{{risk.keywordHits.length}}</strong><small>当前有效事件命中条目</small></div></div>
<el-descriptions :column="1" border><el-descriptions-item label="基础等级">{{level(risk.baseLevel)}}</el-descriptions-item><el-descriptions-item label="规则等级">{{level(risk.ruleLevel)}}</el-descriptions-item><el-descriptions-item label="有效人工调整">{{risk.manualLevel ? level(risk.manualLevel) : '无或已失效'}}</el-descriptions-item><el-descriptions-item label="最近有效事件时间">{{risk.lastEventTime ? formatTime(risk.lastEventTime) : '暂无有效事件'}}</el-descriptions-item><el-descriptions-item label="规则版本">{{risk.ruleVersion}}</el-descriptions-item></el-descriptions>
<p class="risk-note">次数按当前规则版本计算，阈值可在“规则与批量接入”查看。规则等级结合特殊来源与关键词命中，最终等级同时考虑有效人工调整；可信特殊来源至少中风险。人工调整与误命中处理请前往“规则与批量接入 → 误命中与人工调整”。</p><el-alert v-if="risk.specialFloor" title="存在可信特殊账号来源，固定至少中风险" type="warning" :closable="false"/>
<h3>有效事件与来源证据</h3><el-empty v-if="!risk.events.length" description="暂无有效事件证据" :image-size="64"/><el-collapse v-else><el-collapse-item v-for="event in risk.events" :key="event.id" :title="`有效事件：${descriptionSummary(event.sources[0]?.description)} · ${formatTime(event.eventTime)} · ${event.sources.length} 条来源`"><div v-for="source in event.sources" :key="source.recordId" class="risk-source-evidence"><p><el-button class="source-link" link type="primary" :disabled="busy" @click="run(()=>openRecord(source.recordId))">来源记录：{{descriptionSummary(source.description)}}</el-button> · 来源部门：{{source.departmentName || '未知部门'}} · {{source.source}} · {{source.specialReport?'特殊账号来源':'普通来源'}}</p><p class="description">{{source.description}}</p><p>标签：{{source.tags||'无'}}</p></div></el-collapse-item></el-collapse>
<h3>关键词命中证据</h3><p v-if="!risk.keywordHits.length">暂无有效事件命中</p><section class="risk-hit" v-for="hit in risk.keywordHits" :key="`${hit.eventId}-${hit.ruleId}`"><h4>事件 #{{hit.eventId}} · {{hit.ruleName}} · 规则版本 {{hit.ruleVersion}} · 至少中风险</h4><p v-for="(e,index) in hit.evidence" :key="index">来源 #{{e.recordId}} · {{e.field==='tags'?'人工标签':'问题描述'}}：{{e.text.slice(0,e.start)}}<mark>{{e.text.slice(e.start,e.end)}}</mark>{{e.text.slice(e.end)}}</p></section></section>
</section></el-tab-pane>
<el-tab-pane name="duplicates" label="重复审核池"><section class="event-card"><div class="card-heading"><div><h2>重复审核池 <span>{{pending.length}}</span></h2><p class="muted">核对疑似重复记录，确认独立有效或归集到已有来源。</p></div><el-button :disabled="busy" @click="run(refresh)">刷新重复待审</el-button></div><el-table :data="pending" empty-text="暂无身份明确的重复待审记录"><el-table-column prop="id" label="编号" width="80"/><el-table-column prop="party_name" label="当事人" min-width="130"/><el-table-column prop="problem_description" label="描述" min-width="260" show-overflow-tooltip/><el-table-column label="操作" width="120"><template #default="{row}"><el-button link type="primary" :disabled="busy" @click="run(()=>openRecord(row.id))">核查重复</el-button></template></el-table-column></el-table></section></el-tab-pane>
<el-tab-pane name="rules" label="关键词规则"><section class="event-card"><div class="card-heading"><div><h2>关键词规则 <span>{{rules.length}}</span></h2><p class="muted">当前规则只读，编辑与发布请前往“规则与批量接入”。</p></div></div><p class="rules-note">按字面匹配；组合仅在同一有效事件的描述、标签及归集来源之间成立。</p><el-table :data="rules" empty-text="暂无关键词规则"><el-table-column prop="name" label="规则" min-width="220"/><el-table-column prop="version" label="版本" width="100"/><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'" effect="plain">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column></el-table></section></el-tab-pane>
<el-tab-pane name="source" label="来源记录核查">
<section class="event-card source-card"><div class="card-heading"><h2>来源记录核查</h2><span class="muted">查看来源与归集依据</span></div><form class="filter-bar" @submit.prevent="recordId && run(()=>openRecord(Number(recordId)))"><label class="risk-query"><span>来源记录编号</span><el-input v-model="recordId" aria-label="核查来源编号" placeholder="请输入来源记录编号"/></label><el-button type="primary" native-type="submit" :disabled="busy||!recordId">读取来源记录</el-button></form>
<el-empty v-if="!record" description="输入来源编号，或从风险证据、重复审核池进入核查" :image-size="80"/><div v-if="record" class="source-detail"><h3>来源记录 #{{record.id}} · {{record.party_name}}</h3><div class="source-status"><el-tag :type="record.identity_review_state==='CONFIRMED'?'success':'warning'" effect="plain">{{state(record.identity_review_state)}}</el-tag><el-tag type="info" effect="plain">{{state(record.duplicate_review_state)}}</el-tag><span class="muted">{{record.effectiveEventId ? `有效事件 #${record.effectiveEventId}` : '尚未归集'}}</span></div><h4>联系地址</h4><p>{{record.party_address||'未填写'}}</p><h4>问题描述</h4><p class="description">{{record.problem_description}}</p>
<h4>关键词证据（当前来源文本）</h4><p v-if="!record.keywordHits.length" class="empty-evidence">当前来源暂无命中；跨归集来源的组合依据见人员风险档案。</p><div v-for="hit in record.keywordHits" :key="hit.ruleId"><p>{{hit.ruleName}} · 版本 {{hit.ruleVersion}} · {{record.effectiveEventId?'参与风险保底':'待归集，暂不影响人员风险'}}</p><p v-for="(e,i) in hit.evidence" :key="i">{{e.field==='tags'?'标签':'描述'}}：{{e.text.slice(0,e.start)}}<mark>{{e.text.slice(e.start,e.end)}}</mark>{{e.text.slice(e.end)}}</p></div>
<template v-if="!record.effectiveEventId&&record.identity_review_state==='CONFIRMED'"><h4>重复候选</h4><el-table :data="candidates" empty-text="暂无重复候选，请结合来源内容核查"><el-table-column prop="id" label="候选记录" width="100"/><el-table-column prop="description" label="描述" min-width="240" show-overflow-tooltip/><el-table-column prop="secondsApart" label="时间差（秒）" width="140"/><el-table-column prop="similarity" label="相似度" width="100"/></el-table>
<el-form class="duplicate-form" label-position="top" :disabled="busy"><el-form-item label="审核结论"><el-radio-group v-model="decision"><el-radio value="INDEPENDENT">确认独立有效</el-radio><el-radio value="MERGE">确认重复并归集</el-radio></el-radio-group></el-form-item><el-form-item v-if="decision==='MERGE'" label="归集目标来源编号"><el-input-number v-model="target" :min="1" aria-label="归集目标来源编号"/></el-form-item><el-form-item label="重复审核理由" required><el-input v-model="reason" aria-label="重复审核理由" type="textarea" :rows="3" placeholder="请填写判断重复或独立事件的依据"/></el-form-item><el-button type="primary" :loading="busy" @click="run(review)">提交重复审核</el-button></el-form></template>
<section class="tag-section"><h4>人工标签</h4><p class="muted">补充风险关键词，并记录标注依据。</p><el-form class="tag-form" label-position="top" :disabled="busy"><el-form-item label="关键词标签"><el-input v-model="tags" aria-label="人工关键词标签" maxlength="500" placeholder="请输入需要标注的关键词" show-word-limit/></el-form-item><el-form-item label="标注理由" required><el-input v-model="tagReason" aria-label="标签标注理由" placeholder="请填写标签标注理由" type="textarea" :rows="3"/></el-form-item><el-button type="primary" :loading="busy" @click="run(saveTags)">保存关键词标签</el-button></el-form></section>
<h4>重复处理历史</h4><el-table :data="record.duplicateHistory" empty-text="暂无重复处理记录"><el-table-column label="结论" min-width="160"><template #default="{row}">{{historyDecision(row.decision)}}</template></el-table-column><el-table-column prop="reason" label="理由" min-width="200" show-overflow-tooltip/><el-table-column prop="actor_username" label="操作者" min-width="100"/><el-table-column label="时间" width="190"><template #default="{row}"><span class="history-time">{{formatTime(row.created_at)}}</span></template></el-table-column></el-table>
</div></section>
</el-tab-pane>
</el-tabs>
</main>
</template>
